pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // No restrictive assumptions - we want to cover both zero and non-zero addresses.
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        if (success) {
            assertEq(c.owner(), newOwner, "Successful transferOwnership must set owner to newOwner");
        }
    }
}

