pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(newOwner != address(0));
        address prevOwner = c.owner();
        vm.prank(caller);
        c.transferOwnership(newOwner);
        assertTrue(prevOwner == address(this) ? c.owner() == newOwner : c.owner() == prevOwner);
    }
}
